query Users($currentPage: Int = 1, $perPage: Int = 10, $sort: [UserSortType!], $search: String, $filter: UserFilterType, $rand: Boolean = false) {
  users(current_page: $currentPage, per_page: $perPage, sort: $sort, q: $search, filter: $filter, rand: $rand) {
    data {
      id
      phone
      password
      email
      nickname
      age
      profileId
      isDelete
      weight
      state
      deletedBy
      updatedBy
      createdBy
      deletedAt
      updatedAt
      createdAt
      profile {
        ...ProfilesFields
      }
      tasks {
        ...TasksFields
      }
      userRoles {
        ...UserRolesFields
      }

    }
    current_page
    per_page
    total
    total_page
  }
}

query UserDetail($id: ID, $search: String, $filter: UserFilterType) {
  user(id: $id, q: $search, filter: $filter) {
    id
    phone
    password
    email
    nickname
    age
    profileId
    isDelete
    weight
    state
    deletedBy
    updatedBy
    createdBy
    deletedAt
    updatedAt
    createdAt
    profile {
      ...ProfilesFields
    }
    tasks {
      ...TasksFields
    }
    userRoles {
      ...UserRolesFields
    }

  }
}

mutation createUser($data: CreateUserInput!) {
  createUser(input: $data) {
    id
  }
}

mutation updateUser($id: ID!, $data: UpdateUserInput!) {
  updateUser(id: $id, input: $data) {
    id
  }
}

mutation deleteUsers($id: [ID!]!) {
  deleteUsers(id: $id)
